const formatTimeTo24Hour = (timeStr) => {
  if (!timeStr) return "";
  const str = String(timeStr).trim();
  if (/^\d{1,2}:\d{2}$/.test(str)) {
    const [h, m] = str.split(":");
    return `${String(h).padStart(2, "0")}:${m}`;
  }
  const match = str.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (match) {
    let hours = parseInt(match[1], 10);
    const minutes = match[2];
    const ampm = (match[3] || "").toUpperCase();
    if (ampm === "PM" && hours < 12) hours += 12;
    if (ampm === "AM" && hours === 12) hours = 0;
    return `${String(hours).padStart(2, "0")}:${minutes}`;
  }
  return str;
};

// Converts date string (e.g. YYYY-MM-DD or ISO) to DD/MM/YYYY
const formatToDDMMYYYY = (val) => {
  if (!val) return "";
  const str = String(val).trim();
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) return str;
  if (/^\d{4}-\d{2}-\d{2}/.test(str)) {
    const parts = str.split("T")[0].split("-");
    if (parts.length === 3) {
      return `${parts[2].padStart(2, "0")}/${parts[1].padStart(2, "0")}/${parts[0]}`;
    }
  }
  return str;
};

// Converts DD/MM/YYYY to YYYY-MM-DD for HTML5 date inputs
const formatToYYYYMMDD = (val) => {
  if (!val) return "";
  const str = String(val).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    const parts = str.split("/");
    if (parts.length === 3) {
      return `${parts[2]}-${parts[1].padStart(2, "0")}-${parts[0].padStart(2, "0")}`;
    }
  }
  return "";
};

// Checks if a date (DD/MM/YYYY or YYYY-MM-DD or ISO) is expired compared to current date (end of day)
const isDocExpired = (val) => {
  if (!val) return false;
  const str = String(val).trim();
  let expDate = null;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    const [d, m, y] = str.split("/").map(Number);
    expDate = new Date(y, m - 1, d, 23, 59, 59, 999);
  } else if (/^\d{4}-\d{2}-\d{2}/.test(str)) {
    const parts = str.split("T")[0].split("-").map(Number);
    expDate = new Date(parts[0], parts[1] - 1, parts[2], 23, 59, 59, 999);
  } else {
    const parsed = new Date(str);
    if (!isNaN(parsed.getTime())) {
      parsed.setHours(23, 59, 59, 999);
      expDate = parsed;
    }
  }
  if (!expDate || isNaN(expDate.getTime())) return false;
  return expDate < new Date();
};

// Returns number of days remaining until document expiry (null if invalid, negative if expired)
const getDocumentDaysRemaining = (val) => {
  if (!val) return null;
  const str = String(val).trim();
  let expDate = null;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    const [d, m, y] = str.split("/").map(Number);
    expDate = new Date(y, m - 1, d, 23, 59, 59, 999);
  } else if (/^\d{4}-\d{2}-\d{2}/.test(str)) {
    const parts = str.split("T")[0].split("-").map(Number);
    expDate = new Date(parts[0], parts[1] - 1, parts[2], 23, 59, 59, 999);
  } else {
    const parsed = new Date(str);
    if (!isNaN(parsed.getTime())) {
      parsed.setHours(23, 59, 59, 999);
      expDate = parsed;
    }
  }
  if (!expDate || isNaN(expDate.getTime())) return null;
  const diffMs = expDate.getTime() - Date.now();
  return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
};

// Resolves document URL safely (handles full URLs, blob/data URIs, and relative backend paths)
const resolveDocUrl = (rawUrlOrDoc) => {
  if (!rawUrlOrDoc) return "";
  const rawUrl = typeof rawUrlOrDoc === "string" ? rawUrlOrDoc : (rawUrlOrDoc.url || rawUrlOrDoc.documentUrl || "");
  if (!rawUrl || rawUrl === "#") return "";
  if (rawUrl.startsWith("http://") || rawUrl.startsWith("https://") || rawUrl.startsWith("blob:") || rawUrl.startsWith("data:")) {
    return rawUrl;
  }
  const cleanUrl = rawUrl.replace(/\\/g, "/").replace(/^\/+/, "");
  const backend = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/+$/, "");
  return backend ? `${backend}/${cleanUrl}` : `/${cleanUrl}`;
};

